def apply_temp(p: float, t: float) -> float:
    """Temperature on a binary probability, via its logit."""
    p = min(max(p, 1e-6), 1 - 1e-6)
    logit = math.log(p / (1 - p)) / t
    return 1 / (1 + math.exp(-logit))

