def nll(probs: list[float], labels: list[int], t: float) -> float:
    s = 0.0
    for p, y in zip(probs, labels):
        q = apply_temp(p, t)
        q = min(max(q, 1e-9), 1 - 1e-9)
        s -= math.log(q) if y else math.log(1 - q)
    return s / max(len(probs), 1)

